import{_ as r,g as o,o as i,c as n,j as a,a as c,k as d,a2 as l}from"./chunks/framework.DXa1R37q.js";const s={class:"diagram-links"},f=["href"],v={class:"diagram-frame editorial"},b=["src"],_=JSON.parse('{"title":"Lifecycle and authority boundaries","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"learn/lifecycle.md","filePath":"learn/lifecycle.md","lastUpdated":1792970147000}'),p={name:"learn/lifecycle.md"},h=Object.assign(p,{setup(u){const t=o("/diagrams/neottia-lifecycle.html");return(m,e)=>(i(),n("div",null,[e[0]||(e[0]=a("h1",{id:"lifecycle-and-authority-boundaries",tabindex:"-1"},[c("Lifecycle and authority boundaries "),a("a",{class:"header-anchor",href:"#lifecycle-and-authority-boundaries","aria-label":'Permalink to "Lifecycle and authority boundaries"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Neottia installs six public commands. Four advance delivery work. Two help recover context without silently advancing it.",-1)),a("div",s,[a("a",{href:d(t),target:"_blank",rel:"noreferrer"},"Open the interactive lifecycle in a new tab",8,f)]),a("div",v,[a("iframe",{src:d(t),title:"Interactive Neottia lifecycle and authority diagram",loading:"lazy"},null,8,b)]),e[2]||(e[2]=l('<h2 id="delivery-commands" tabindex="-1" data-v-b3d019f7>Delivery commands <a class="header-anchor" href="#delivery-commands" aria-label="Permalink to &quot;Delivery commands&quot;" data-v-b3d019f7>​</a></h2><table tabindex="0" data-v-b3d019f7><thead data-v-b3d019f7><tr data-v-b3d019f7><th data-v-b3d019f7>Command</th><th data-v-b3d019f7>Owns</th><th data-v-b3d019f7>Required stop</th></tr></thead><tbody data-v-b3d019f7><tr data-v-b3d019f7><td data-v-b3d019f7><code data-v-b3d019f7>/plan</code></td><td data-v-b3d019f7>Requirements, repository evidence, owning Epic, child work, and design scope</td><td data-v-b3d019f7>Stop for current scope or design approval</td></tr><tr data-v-b3d019f7><td data-v-b3d019f7><code data-v-b3d019f7>/build</code></td><td data-v-b3d019f7>Only the approved implementation scope</td><td data-v-b3d019f7>Stop with implementation evidence for Verify</td></tr><tr data-v-b3d019f7><td data-v-b3d019f7><code data-v-b3d019f7>/verify</code></td><td data-v-b3d019f7>Requirement coverage, checks, user-visible behavior, and verdict</td><td data-v-b3d019f7>Return defects to Build or present a current pass verdict</td></tr><tr data-v-b3d019f7><td data-v-b3d019f7><code data-v-b3d019f7>/release</code></td><td data-v-b3d019f7>Release metadata and one explicitly selected action</td><td data-v-b3d019f7>Stop before any action that lacks fresh authorization</td></tr></tbody></table><h2 id="recovery-commands" tabindex="-1" data-v-b3d019f7>Recovery commands <a class="header-anchor" href="#recovery-commands" aria-label="Permalink to &quot;Recovery commands&quot;" data-v-b3d019f7>​</a></h2><ul data-v-b3d019f7><li data-v-b3d019f7><code data-v-b3d019f7>/continue</code> reads durable records and recommends exactly one next public command. It does not invoke that command.</li><li data-v-b3d019f7><code data-v-b3d019f7>/refresh</code> reloads configuration, provider records, repository state, and source-control state. It reports drift without changing phase.</li></ul><h2 id="approval-rules" tabindex="-1" data-v-b3d019f7>Approval rules <a class="header-anchor" href="#approval-rules" aria-label="Permalink to &quot;Approval rules&quot;" data-v-b3d019f7>​</a></h2><p data-v-b3d019f7>Approval is narrow and current:</p><ul data-v-b3d019f7><li data-v-b3d019f7>Plan approval covers the recorded implementation scope.</li><li data-v-b3d019f7>It does not authorize merge, publication, deployment, remote closure, or destructive cleanup.</li><li data-v-b3d019f7>Release can prepare one action, but the action still needs explicit owner authorization.</li><li data-v-b3d019f7>A confirmed defect becomes one canonical Bug and returns through Build.</li><li data-v-b3d019f7>A stop records the exact revision, commits, checks, status, and recommended next command in an append-only checkpoint.</li></ul><p data-v-b3d019f7>These rules remain the same in Pi, OpenCode, and Claude Code. Adapters change host syntax and paths, not lifecycle authority.</p><p data-v-b3d019f7>Read the <a href="/projects/neottia/sdlc/protocol" data-v-b3d019f7>operating protocol reference</a> for the full checkpoint and ownership contract. See <a href="/projects/neottia/reference/diagrams" data-v-b3d019f7>diagram sources and attribution</a> for evidence and license details.</p>',9))]))}}),g=r(h,[["__scopeId","data-v-b3d019f7"]]);export{_ as __pageData,g as default};
